/// Runtime settings store (Docs/App/Settings.md).
///
/// Persisted as a simple JSON file under the user's config directory on desktop
/// and the app's private temp directory on mobile; kept in RAM only when neither
/// is available (see [_settingsFile]).
library;

import 'dart:convert';
import 'dart:io';

import 'package:flutter/foundation.dart';

import 'app_version.g.dart';
import 'platform_caps.dart';

/// The app's deterministic version (generated by scripts/gen_app_version.py from app/lib
/// content). The compile date stays as a build-time marker for diagnostics.
const String appVersion = kAppVersion;
const String appBuildDate = String.fromEnvironment(
  'APP_BUILD_DATE',
  defaultValue: 'unknown',
);

/// Notification events offered for per-event selection.
const List<String> notificationEvents = [
  'Device discovered',
  'Device lost',
  'Backup finished',
];

class AppSettings extends ChangeNotifier {
  AppSettings._();

  static final AppSettings instance = AppSettings._();

  bool autoConnect = false;
  String autoConnectDeviceId = '';

  /// Notifications while the app is open.
  bool notifyInApp = true;
  final Set<String> inAppEvents = {...notificationEvents};

  /// "If app open do not notify OS" (true/false).
  bool suppressOsWhenOpen = true;

  /// Notifications handed to the operating system.
  bool notifyOs = false;
  final Set<String> osEvents = {...notificationEvents};

  Future<void> load() async {
    final file = _settingsFile();
    if (file == null || !file.existsSync()) return;
    try {
      final data = jsonDecode(file.readAsStringSync()) as Map<String, dynamic>;
      autoConnect = data['autoConnect'] as bool? ?? false;
      autoConnectDeviceId = data['autoConnectDeviceId'] as String? ?? '';
      notifyInApp = data['notifyInApp'] as bool? ?? true;
      inAppEvents
        ..clear()
        ..addAll(
          (data['inAppEvents'] as List<dynamic>? ?? notificationEvents)
              .cast<String>(),
        );
      suppressOsWhenOpen = data['suppressOsWhenOpen'] as bool? ?? true;
      notifyOs = data['notifyOs'] as bool? ?? false;
      osEvents
        ..clear()
        ..addAll(
          (data['osEvents'] as List<dynamic>? ?? notificationEvents)
              .cast<String>(),
        );
      notifyListeners();
    } catch (_) {
      // Corrupt settings are ignored; defaults stay in effect.
    }
  }

  Future<void> save() async {
    final file = _settingsFile();
    if (file == null) return;
    try {
      file.createSync(recursive: true);
      await file.writeAsString(
        jsonEncode({
          'autoConnect': autoConnect,
          'autoConnectDeviceId': autoConnectDeviceId,
          'notifyInApp': notifyInApp,
          'inAppEvents': inAppEvents.toList(),
          'suppressOsWhenOpen': suppressOsWhenOpen,
          'notifyOs': notifyOs,
          'osEvents': osEvents.toList(),
        }),
      );
    } catch (_) {}
  }

  void update(void Function() change) {
    change();
    notifyListeners();
    save();
  }

  /// The persisted settings location. Android exposes no HOME, so it uses the
  /// process's own temp/cache directory, which `dart:io` resolves from the
  /// platform's TMPDIR (app-private, no path_provider plugin). Desktops keep the
  /// existing `~/.config/tamuapp` path so already-saved settings are not orphaned.
  static File? _settingsFile() {
    try {
      if (isMobile) {
        return File('${Directory.systemTemp.path}/settings.json');
      }
      final home =
          Platform.environment['HOME'] ?? Platform.environment['USERPROFILE'];
      if (home == null || home.isEmpty) return null;
      return File('$home/.config/tamuapp/settings.json');
    } catch (_) {
      return null;
    }
  }
}
